	$showFooterMenu = get_theme_mod('show_footer_menu', SHOW_FOOTER_MENU);
	$contactTitle = get_theme_mod('footer_contact_title', FOOTER_CONTACT_TITLE);
	$showAddress = get_theme_mod('show_footer_address', SHOW_FOOTER_ADDRESS);
	$addressTitle = get_theme_mod('footer_address_title', FOOTER_ADDRESS_TITLE);
	$showSocials = get_theme_mod('show_footer_social', SHOW_FOOTER_SOCIAL);
	$showCopy = get_theme_mod('show_footer_copyright', SHOW_FOOTER_COPYRIGHT);
	$copyText = get_theme_mod('footer_copyright_text', FOOTER_COPYRIGHT_TEXT);
	$showPolicy = get_theme_mod('show_footer_policy', SHOW_FOOTER_POLICY);
	$showPopup = get_theme_mod('show_footer_accept_popup', SHOW_FOOTER_ACCEPT_POPUP);
	$policyText = get_theme_mod('footer_accept_popup_text', FOOTER_ACCEPT_POPUP_TEXT);
	$policyBtnText = get_theme_mod('policy_popup_button_text', POLICY_POPUP_BUTTON_TEXT);
	$sitemap_show = get_theme_mod('sitemap_show', SITEMAP_SHOW);
